CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_EV_CHARGING_DAY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_EV_CHARGING at grain Date.FullDate, Date.IsWeekend, Date.MonthName, Date.MonthNumber; covers 17.37% of weighted demand (1 clusters); est. 2,200 rows; ~0.0167 credits/day'
AS
SELECT d1.FULL_DATE,
       d1.IS_WEEKEND,
       d1.MONTH_NAME,
       d1.MONTH_NUMBER,
       SUM(f.COST) AS COST,
       SUM(f.ENERGY_DELIVERED_KWH) AS ENERGY_DELIVERED_KWH,
       MAX(f.PEAK_KW) AS PEAK_KW,
       COUNT(*) AS EV_CHARGING_COUNT
FROM CORE.FCT_EV_CHARGING f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
GROUP BY ALL;
